begin;
set local statement_timeout='55s';
select pg_advisory_xact_lock(hashtextextended('chem-source-original-release',0));
select pg_advisory_xact_lock(hashtextextended('chem-h3-original-release',0));
create temporary table h1_parent_review_input as select * from jsonb_to_recordset($proof$[{"old_id": "QH1O_008AC0309A70_234162C2EA9C5CF9_E26C51BDCB459E77", "new_id": "QH1PARENT02_234162C2EA9C5CF9", "source_key": "234162c2ea9c5cf9037df91a9e0788a1b2f0f0babd3454ef0a5495a3ee31180a", "expected_revision": "e26c51bdcb459e7716fad261e28148fb0011ec2f538533e81de98495f71ae505", "source_document_sha256": "17cdf734a9b4c0c4759ee89a90c8e253157dc167ab64aad7c231d952eeb561be", "source_title": "1.3 物质的分散系（讲义）", "block": 126, "question_no": "1", "concept_key": "H1_ELECTROLYTE__C52", "skill_id": "H1_ELECTROLYTE", "correct_option": 1, "canonical_source_id": "H1M_20260912_17_0126", "question_sha": "a31d83ffca31121b51546da9b846ca04aedb20fa7cbe2b8d2f463a3dd252cc6f", "analysis_sha": "f0e70d8714b4be9376b586765f4bed2e35d514b2706c64048bb72d4c54dcf0e4", "date": "2026-10-05"}, {"old_id": "QH1O_008AC0309A70_35C30AA9239EB55F_6DED8971CED376C5", "new_id": "QH1PARENT02_35C30AA9239EB55F", "source_key": "35c30aa9239eb55f3f0aa1fe6c0f578f75a2b2afc5a186558c6c43f7ba629c3a", "expected_revision": "6ded8971ced376c5586822e3312c3b85718e3e1ad856c349f409236b8d73911b", "source_document_sha256": "17cdf734a9b4c0c4759ee89a90c8e253157dc167ab64aad7c231d952eeb561be", "source_title": "1.3 物质的分散系（讲义）", "block": 224, "question_no": "2", "concept_key": "H1_ELECTROLYTE__C52", "skill_id": "H1_ELECTROLYTE", "correct_option": 3, "canonical_source_id": "H1M_20260912_17_0224", "question_sha": "e8187444e6ad5f576f7d23edae787e2530090415b3be869713cab0802f86ab24", "analysis_sha": "e85ff85a694492c832a1a4d47b3bf5f91501701feac7033757d097fbd1596ede", "date": "2026-10-05"}, {"old_id": "QH1O_008AC0309A70_4D4D40236159F9B0_F8BC332FDFCA6DDA", "new_id": "QH1PARENT02_4D4D40236159F9B0", "source_key": "4d4d40236159f9b0d8fb2e1b5d514de737f9e162beaa19fd5c6537bef8bed864", "expected_revision": "f8bc332fdfca6dda24cdbd1655ddfb70002fdc953e67749004f0c4fb4fd91bba", "source_document_sha256": "443c515fb9322006358341360a242a2252af5fa6600f8705f06b1468bc9ba091", "source_title": "3.2 金属钠与钠的化合物 第3课时 离子反应（讲义）", "block": 255, "question_no": "2", "concept_key": "H1_ELECTROLYTE__C53", "skill_id": "H1_ELECTROLYTE", "correct_option": 3, "canonical_source_id": "H1M_20260912_59_0255", "question_sha": "6583f0752e3622c3a5751e82ea868fdf0223b9fba9b70e8a07d458ec5245b9a2", "analysis_sha": "7f9cacce07fd58a63011065adcffb25de17458ddd88269ae68f913b43147e1c1", "date": "2026-10-05"}, {"old_id": "QH1O_008AC0309A70_85E853A1173096A8_5C0BD9CBBA291303", "new_id": "QH1PARENT02_85E853A1173096A8", "source_key": "85e853a1173096a87c5f3bd892b051137b05719bbb263bec7f2d330f5ee3b8a1", "expected_revision": "5c0bd9cbba29130302f33f359110d2ffe5e7f8cbe882151106acab8d1a945f6e", "source_document_sha256": "17cdf734a9b4c0c4759ee89a90c8e253157dc167ab64aad7c231d952eeb561be", "source_title": "1.3 物质的分散系（讲义）", "block": 569, "question_no": "1", "concept_key": "H1_ELECTROLYTE__C52", "skill_id": "H1_ELECTROLYTE", "correct_option": 3, "canonical_source_id": "H1M_20260912_17_0569", "question_sha": "3d4f0c289d4e4ab21e3f9e221d4e8fce02df1580bf8a37f7fd85a51700da298e", "analysis_sha": "da5c3748cfe8c3e50bd0fc6583c1d69e3e2428df69a2bce76ff7c4eeb1156fb7", "date": "2026-10-05"}, {"old_id": "QH1O_008AC0309A70_C9F8B5921233835C_3BADD7804FEDC57D", "new_id": "QH1PARENT02_C9F8B5921233835C", "source_key": "c9f8b5921233835c843e22a74f165eddce5b297f56ce88d8bf8409bdf8fe966d", "expected_revision": "3badd7804fedc57d2ddb88132969fd822ab11c6c08c422ddbbf2172720514242", "source_document_sha256": "17cdf734a9b4c0c4759ee89a90c8e253157dc167ab64aad7c231d952eeb561be", "source_title": "1.3 物质的分散系（讲义）", "block": 188, "question_no": "1", "concept_key": "H1_ELECTROLYTE__C52", "skill_id": "H1_ELECTROLYTE", "correct_option": 3, "canonical_source_id": "H1M_20260912_17_0188", "question_sha": "72a797255a96a3552d084753030c5c520cd4238661b23a33d0567c7e4fcde262", "analysis_sha": "cd5ffb53b151f6e530ca09ba466db47e3cf338639417dca68953b8da2e6fb451", "date": "2026-10-05"}]$proof$::jsonb)
 as x(old_id text,new_id text,source_key text,expected_revision text,source_document_sha256 text,source_title text,block integer,question_no text,concept_key text,skill_id text,correct_option integer,canonical_source_id text,question_sha text,analysis_sha text,date date);
select q.id from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id order by q.id for update of q;
create temporary table h1_parent_old_questions as select q.id,to_jsonb(q)-array['usable_for_review','usable_for_class_quiz','usable_for_exam_sprint','usable_for_demo','updated_at'] row_data from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
create temporary table h1_parent_old_answers as select a.* from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id;
create temporary table h1_parent_old_locks as select a.* from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id;
do $guard$ begin
 if (select count(*) from h1_parent_old_questions)<>5 or exists(select 1 from app_private.chem_question_source_releases where id='02cb547e-1afa-4c10-8ba7-a7085c0463d9') then raise exception 'Baseline missing or repair already applied';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id where
   q.question_revision_token<>x.expected_revision or q.source_item_key<>x.source_key or q.parent_source_item_key is not null
   or q.source_release_id<>'8da16477-6e5e-59bd-9065-279d28c62b30' or q.concept_key<>x.concept_key or q.correct_option<>x.correct_option
   or x.source_key<>encode(extensions.digest('docx:'||x.source_document_sha256||'|questionStartBlock:'||x.block,'sha256'),'hex')) then raise exception 'Reviewed source identity changed';end if;
 if exists(select 1 from h1_parent_review_input x where not exists(select 1 from app_private.chem_teaching_ready_questions q where q.id=x.old_id)) then raise exception 'Old reviewed source is no longer ready';end if;
 if exists(select 1 from h1_parent_review_input x where
   not exists(select 1 from app_private.chem_question_assets a where a.question_id=x.old_id and a.asset_kind='question_image' and a.sha256=x.question_sha)
   or not exists(select 1 from app_private.chem_question_assets a where a.question_id=x.old_id and a.asset_kind='analysis_image' and a.sha256=x.analysis_sha)) then raise exception 'Visually verified asset changed';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_review_input x on q.id=x.new_id or q.parent_source_item_key=x.source_key) then raise exception 'An existing parent revision needs reconciliation';end if;
end $guard$;
insert into app_private.chem_question_delivery_holds(anchor_question_id,reason)
select old_id,'2026-10-02 DOCX原件顶层题身份已核验；旧导入缺少parent身份，保留历史，改用明确原始母题的新修订。题干、选项和答案不变。' from h1_parent_review_input;
insert into app_private.chem_question_source_releases(id,manifest_sha256,grade_band,status,expected_question_count,verification_status,revision_contract,release_kind)
values('02cb547e-1afa-4c10-8ba7-a7085c0463d9',encode(extensions.digest('h1-source-parent-proof-20261002','sha256'),'hex'),'高一','staged',5,'pending','v2_explanation_assets','teaching_material');
insert into public.chem_questions
select (jsonb_populate_record(null::public.chem_questions,to_jsonb(q)||jsonb_build_object(
 'id',x.new_id,'source_release_id','02cb547e-1afa-4c10-8ba7-a7085c0463d9','mother_id','MH1PARENT01_'||upper(substr(x.source_key,1,16)),
 'source_item_key',encode(extensions.digest(x.source_key||'|parent-proof-20261002','sha256'),'hex'),'parent_source_item_key',x.source_key,
 'usable_for_review',false,'usable_for_class_quiz',false,'usable_for_exam_sprint',false,'usable_for_demo',false,
 'source_info',q.source_info||jsonb_build_object('questionNo',x.question_no,'locator','已核验原DOCX SHA256 '||x.source_document_sha256||' · 顶层题起点 block '||x.block,
   'transcriptionAuditMethod','Original ZIP/DOCX identity, whole original choice, original teacher explanation and current sealed assets individually verified 2026-10-02'),
 'asset_refs',(select jsonb_agg(ref||jsonb_build_object('path','h1parent20261002/'||lower(x.new_id)||'/'||(ref->>'kind')) order by ref->>'kind') from jsonb_array_elements(q.asset_refs) ref),
 'created_at',now(),'updated_at',now()))).*
from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
insert into app_private.chem_question_assets(asset_path,question_id,asset_kind,mime_type,payload_base64,sha256,width,height)
select 'h1parent20261002/'||lower(x.new_id)||'/'||a.asset_kind,x.new_id,a.asset_kind,a.mime_type,a.payload_base64,a.sha256,a.width,a.height
from app_private.chem_question_assets a join h1_parent_review_input x on x.old_id=a.question_id;
update public.chem_questions q set question_revision_token=app_private.chem_h3_question_revision_sha256(q,a.sha256,b.sha256)
from app_private.chem_question_assets a,app_private.chem_question_assets b where q.source_release_id='02cb547e-1afa-4c10-8ba7-a7085c0463d9' and a.question_id=q.id and a.asset_kind='question_image' and b.question_id=q.id and b.asset_kind='analysis_image';
insert into app_private.chem_question_source_release_items(release_id,question_id,canonical_source_id,question_asset_sha256,analysis_asset_sha256,item_sha256)
select '02cb547e-1afa-4c10-8ba7-a7085c0463d9',q.id,x.canonical_source_id,a.sha256,b.sha256,app_private.chem_h3_release_item_sha256(q,x.canonical_source_id,a.sha256,b.sha256)
from public.chem_questions q join h1_parent_review_input x on x.new_id=q.id join app_private.chem_question_assets a on a.question_id=q.id and a.asset_kind='question_image' join app_private.chem_question_assets b on b.question_id=q.id and b.asset_kind='analysis_image';
update app_private.chem_question_source_releases r set manifest_sha256=(select encode(extensions.digest(convert_to(string_agg(i.item_sha256,E'\n' order by i.question_id),'UTF8'),'sha256'),'hex') from app_private.chem_question_source_release_items i where i.release_id=r.id) where id='02cb547e-1afa-4c10-8ba7-a7085c0463d9';
select public.chem_record_question_item_visual_review(q.id,q.question_revision_token,q.source_info->>'locator','codex-source-parent-audit-20261002',
 '2026-10-02 原ZIP恢复DOCX，SHA256='||x.source_document_sha256||'，第'||x.block||'块开始的独立顶层选择题，原题号'||x.question_no||'。原文四选项和原教师答案、现行封装题图与解析图逐项核验，唯一答案'||substr('ABCD',x.correct_option+1,1)||'。题干、选项和解析文字未改动，仅明确原始母题身份；不是新编题或一个大题拆出的独立母题。',
 '{"stem_options_and_formula":true,"answer_and_explanation":true,"source_image_complete":true,"source_locator_matches":true}'::jsonb)
from public.chem_questions q join h1_parent_review_input x on x.new_id=q.id;
insert into app_private.chem_question_source_release_lineage(release_id,question_id,previous_release_id,previous_question_id)
select '02cb547e-1afa-4c10-8ba7-a7085c0463d9',x.new_id,q.source_release_id,q.id from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
select public.chem_mark_source_original_release_visually_verified('02cb547e-1afa-4c10-8ba7-a7085c0463d9',(select manifest_sha256 from app_private.chem_question_source_releases where id='02cb547e-1afa-4c10-8ba7-a7085c0463d9'),'codex-full-visual-qa');
select * from public.chem_activate_teaching_material_release('02cb547e-1afa-4c10-8ba7-a7085c0463d9',(select manifest_sha256 from app_private.chem_question_source_releases where id='02cb547e-1afa-4c10-8ba7-a7085c0463d9'));
insert into app_private.chem_teaching_question_topics(question_id,topic_id,evidence)
select x.new_id,t.topic_id,jsonb_build_object('method','visually_verified_revision_lineage','evidence',jsonb_build_object('parentQuestionId',x.old_id,'sourceReleaseId','02cb547e-1afa-4c10-8ba7-a7085c0463d9','sourceLocator',q.source_info->>'locator','sourceDocumentSha256',x.source_document_sha256,'basis','unchanged original question, DOCX top-level parent provenance restored'),'sameTypeClaim',false,'questionRevisionToken',q.question_revision_token)
from h1_parent_review_input x join app_private.chem_teaching_question_topics t on t.question_id=x.old_id join public.chem_questions q on q.id=x.new_id;
do $qa$ begin
 if exists(select 1 from public.chem_questions n join h1_parent_review_input x on x.new_id=n.id join public.chem_questions o on o.id=x.old_id
   where n.content_fingerprint<>o.content_fingerprint or
   app_private.chem_choice_repetition_state(to_jsonb(n),jsonb_build_array(to_jsonb(o)||jsonb_build_object('study_date','2026-10-02','answered_at','2026-10-02T00:00:00+08:00','correct',true,'uncertain',false)),date '2026-10-02')->>'kind'<>'same_day_or_pending'
   or app_private.chem_choice_repetition_state(to_jsonb(n),jsonb_build_array(to_jsonb(o)||jsonb_build_object('study_date','2026-09-30','answered_at','2026-09-30T00:00:00+08:00','correct',true,'uncertain',false)),date '2026-10-02')->>'kind'<>'due_review') then raise exception 'Revision would be mistaken for a new original instead of retaining its review history';end if;
 if (select count(*) from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.new_id=q.id where app_private.chem_choice_parent_identity(to_jsonb(q))=x.source_key)<>5 then raise exception 'Five source-reviewed identifiable questions not ready';end if;
 if exists(select 1 from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.old_id=q.id) then raise exception 'Superseded old question remains deliverable';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_old_questions b on b.id=q.id where to_jsonb(q)-array['usable_for_review','usable_for_class_quiz','usable_for_exam_sprint','usable_for_demo','updated_at']<>b.row_data) then raise exception 'Original question or identity changed';end if;
 if exists((select to_jsonb(a) from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id except select to_jsonb(a) from h1_parent_old_answers a)
 union all (select to_jsonb(a) from h1_parent_old_answers a except select to_jsonb(a) from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id)) then raise exception 'Old answers changed';end if;
 if exists((select to_jsonb(a) from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id except select to_jsonb(a) from h1_parent_old_locks a)
 union all (select to_jsonb(a) from h1_parent_old_locks a except select to_jsonb(a) from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id)) then raise exception 'Old answer locks changed';end if;
end $qa$;
select q.id,q.concept_key,q.parent_source_item_key,app_private.chem_question_item_delivery_review_ready(q.id) item_review_ready
from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.new_id=q.id order by q.concept_key;
commit;
